+                         ' && exit 0; fi' +
+                         ' && git -c user.name=sm-silent-update' +
+                         ' -c user.email=sm-silent-update@users.noreply.github.com' +
+                         ' merge --no-edit FETCH_HEAD' +
+                         ' && git push ' +
+                         validationLivenessModule.forkPushTokenUrl(forkFull) +
+                         ' HEAD:' + branchName
+            });
+        }
